class ApronFishStoreFace extends StatelessWidget {
  final ApronFishStoreFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronFishStoreFace({
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronFishStoreFaceExpression.surprised:
        svgString = _fishStoreFaceSurprised;
      case ApronFishStoreFaceExpression.smileNonHachimaki:
        svgString = _fishStoreFaceSmileNonHachimaki;
      case ApronFishStoreFaceExpression.worry:
        svgString = _fishStoreFaceWorry;
      case ApronFishStoreFaceExpression.smile:
        svgString = _fishStoreFaceSmile;
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
}
